// Importing useCallback from React
import React, { useState, useEffect, useCallback, useRef } from 'react';

// Creating a reference to the Slider component
const sliderRef = useRef();

// Accessing the slider methods and properties using the reference
sliderRef.current.slickPause(); // Pauses the autoplay
sliderRef.current.slickPlay(); // Resumes the autoplay
sliderRef.current.slickGoTo(3); // Goes to the fourth slide (index starts from 0)
sliderRef.current.innerSlider.addEventListener('click', handleClick); // Adds a click event listener to the slider

// Defining the fetchMovies function using useCallback
const fetchMovies = useCallback(async () => {
  const response = await fetch(
    'https://api.themoviedb.org/3/movie/popular?api_key=499d99db6ce23991d21afde0deede0f1'
  );    
  const data = await response.json();
  setMovies(data.results);
}, []); // Passing an empty array as the dependency array

